        const targetRecord = index.diagrams[activePath.at(-1) ?? '']
        const session = this.dependencies.getEditSession()
        if (session.read.getDirtySnapshot() && session.read.getSessionSnapshot()?.sourceDiagramId !== targetRecord?.id) {
